from dotdict import dotdict
import torch

# Check if the input batch is a PyTorch tensor
if isinstance(batch, torch.Tensor):
    # Move the tensor to the CUDA device
    return batch.to(device)

# Check if the input batch is a tuple or list
elif isinstance(batch, (tuple, list)):
    # Recursively apply to_cuda to each element
    return type(batch)([to_cuda(x, device, ignore_list) for x in batch])

# Check if the input batch is a dictionary
elif isinstance(batch, dict):
    # Create a new dotdict
    new_batch = dotdict()

    # Iterate over each key-value pair in the dictionary
    for k, v in batch.items():
        # If the key is "meta", ignore the value
        if k != 'meta':
            # Recursively apply to_cuda to the value
            new_batch[k] = to_cuda(v, device, ignore_list)
        else:
            # Otherwise, keep the original value
            new_batch[k] = v

    # Return the new dotdict
    return new_batch

# If the input batch is not a tuple, list, dictionary, or PyTorch tensor, raise a TypeError
else:
    raise TypeError("Unsupported input type: {}".format(type(batch)))

