import numpy as np
import torch

# If the input is a torch.Tensor or np.ndarray, we can directly add a new dimension at the zeroth position
if isinstance(batch, (torch.Tensor, np.ndarray)):
    return batch.unsqueeze(0)

# If the input is a tuple or list, we'll recursively apply the `add_batch` function to each element
elif isinstance(batch, (tuple, list)):
    batch = [add_batch(b) for b in batch]
    return torch.stack(batch) if isinstance(batch[0], torch.Tensor) else np.stack(batch)

# If the input is a dictionary, we'll recursively apply the `add_batch` function to each value
elif isinstance(batch, dict):
    batch = {key: add_batch(value) for key, value in batch.items()}
    return torch.stack(list(batch.values())) if all(isinstance(value, torch.Tensor) for value in batch.values()) else np.stack(list(batch.values()))

# If the input is a single item like an integer or a string, we'll return it as is
else:
