def _resolve_dir(output_dir: str) -> str:
    """
    Resolves the output directory path. It might handle cases like creating the directory if it doesn't exist, or normalizing the path.
    """
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)
    return os.path.abspath(output_dir)

def _check_chunking(chunk_size: Optional[int], chunk_bytes: Optional[Union[int, str]]) -> bool:
    """
    Checks if either `chunk_size` or `chunk_bytes` is defined.
    """
    return chunk_size is not None or chunk_bytes is not None

def _chunk_data(inputs: Sequence[Any], chunk_size: Optional[int], chunk_bytes: Optional[Union[int, str]]) -> Sequence[Any]:
    """
    Chunks the input data based on either `chunk_size` or `chunk_bytes`.
    """
    if _check_chunking(chunk_size, chunk_bytes):
        if chunk_size is not None:
            return [inputs[i:i + chunk_size] for i in range(0, len(inputs), chunk_size)]
        elif isinstance(chunk_bytes, int):
            chunked_data = []
            current_chunk = []
            total_bytes = 0
            for item in inputs:
                item_bytes = len(str(item).encode('utf-8'))
                if total_bytes + item_bytes > chunk_bytes:
                    chunked_data.append(current_chunk)
                    current_chunk = [item]
                    total_bytes = item_bytes
                else:
                    current_chunk.append(item)
                    total_bytes += item_bytes
            if current_chunk:
                chunked_data.append(current_chunk)
            return chunked_data
        else:
            raise ValueError("Invalid type for `chunk_bytes`. It should be an integer or a string.")
    else:
        return [inputs]

def _apply_function(fn: Callable[[Any], Any], chunked_data: Sequence[Any]) -> None:
