import jax.numpy as jnp
# Define the log1p function
def log1p(x):
  return jnp.log(1 + x)

# Define the derivative of the log1p function
def log1p_derivative(x):
  return 1 / (1 + x)

# Define the safe input range
safe_range = (-0.999, 1e10)  # Avoiding -1 and very large values

# Clip the input value to the safe range
x = jnp.clip(x, safe_range[0], safe_range[1])

# Use generate_safe_fn to create the safe version of the log1p function
safe_log1p_fn = jax.experimental.stax.generate_safe_fn(log1p, log1p_derivative, safe_range)

# Return the result of the safe log1p operation
return safe_log1p_fn(x)

import jax.numpy as jnp

# Compute cumulative sum of vp
acc0 = jnp.cumsum(vp)

# If use_avg is True, compute the weighted average
if use_avg:
  # Compute the width of each interval in tp
  widths = jnp.diff(tp)

  # Resample vp and these widths into t
  resampled = jnp.vectorize(jnp.interp)(acc0, tp, t) * widths
  return jnp.sum(resampled, axis=-1)
else:
  # Resample acc0 at points t using tp as x-coordinates
  return jnp.vectorize(jnp.interp)(acc0, tp, t)

